examples.config:
FileSet {
  Name = LinuxAll
  Include {
    Options {
      Signature = XXH128
      Compression = LZ4
      One FS = no
      FS Type = ext4, xfs, btrfs
    }
    Options {
      Wild Dir = "*/.cache"
      Wild File = "*.tmp"
      Exclude = yes
    }
    File = /
    Exclude Dir Containing = .nobackup
  }
  Exclude {
    File = /var/lib/bareos
    File = /proc
    File = /tmp
  }
}

FileSet {
  Name = PostgreSQL
  Include {
    Options {
      Signature = XXH128
    }
    Plugin = "python3:module_name=bareos-fd-postgresql"
  }
}

FileSet {
  Name = LinuxAll
  Description = "All local file systems"
}

FileSet {
  Name = LinuxAll
  Include {
    Options {
      Signature = XXH128
    }
    File = /etc
    File = /home
  }
}

FileSet {
  Name = LinuxAll
  Exclude {
    File = /home/*/.cache
    File = /tmp
  }
}

FileSet {
  Name = LinuxAll
  Ignore File Set Changes = yes
}

FileSet {
  Name = LinuxAll
  Enable VSS = yes
}
